import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;

public final class CreditPublisher {
  private final HttpClient client = HttpClient.newBuilder()
      .connectTimeout(Duration.ofSeconds(1)).build();
  private final String baseUrl = System.getenv("CREDIT_BASE_URL");
  public int grant(String operationId) throws IOException, InterruptedException {
    var request = HttpRequest.newBuilder(URI.create(baseUrl + "/credit"))
        .timeout(Duration.ofSeconds(2))
        .header("Content-Type", "application/json")
        .header("X-Operation-ID", operationId)
        .POST(HttpRequest.BodyPublishers.ofString("{\"account\":\"a17\",\"amount\":1}"))
        .build();
    return client.send(request, HttpResponse.BodyHandlers.discarding()).statusCode();
  }
}

